// src/pages/Security/SecurityPage.jsx
import React, { useState, useEffect } from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './Security.css'; 

const SecurityPage = () => {
  const context = useOutletContext();
  const location = useLocation();
  const isDashboard = location.pathname === '/sec';

  // Extract from the 'sec' silo defined in MainLayout
  const { data: secData, setter: setSecData } = context?.sec || {};

  const [scanType, setScanType] = useState('static');
  const [targetUrl, setTargetUrl] = useState('');
  const [scanning, setScanning] = useState(false);

  const runSecurityScan = async () => {
    setScanning(true);
    try {
      const response = await fetch('http://localhost:8000/api/security/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: scanType, url: targetUrl || "N/A" }),
      });
      const data = await response.json();
      
      // Update global state via setter
      if (setSecData) setSecData(data);
    } catch (error) {
      console.error("Scan failed:", error);
    } finally {
      setScanning(false);
    }
  };

  return (
    <div className="soc-container">
      <ProjectNavbar basePath="sec" links={["Threats", "Logs", "Integrity", "VPC"]} />
      
      <div className="p-8">
        {isDashboard && (
          <div className="security-dashboard">
             <h2>Security Operations Center (SOC)</h2>
             <button onClick={() => setScanType('static')}>Static Scan</button>
             <button onClick={() => setScanType('dynamic')}>External Scan</button>
             <button onClick={runSecurityScan} disabled={scanning}>
               {scanning ? 'Analyzing...' : 'Initiate Scan'}
             </button>
             {secData && <pre>{JSON.stringify(secData, null, 2)}</pre>}
          </div>
        )}
        
        {/* Outlet allows P1-P4 to access the 'sec' data */}
        <Outlet context={context} /> 
      </div>
    </div>
  );
};

export default SecurityPage;
